var insertGreatestCommonDivisors = function(head) {
    function gcd(a, b) {
        while (b !== 0) {
            const remainder = a % b;
            a = b;
            b = remainder;
        }
        return a;
    }
    let current = head;
    while (current && current.next) {
        const next = current.next;
        const value = gcd(current.val, next.val);
        current.next = new ListNode(value, next);
        current = next;
    }
    return head;
};

